add_filter( 'woocommerce_account_downloads_columns', 'perfectpixel_review_column_in_downloads', 20 );
add_action( 'woocommerce_account_downloads_column_perfectpixel-review', 'perfectpixel_review_column_value' );

function perfectpixel_review_column_in_downloads( $columns ) {
	if ( wc_reviews_enabled() ) {
		$columns['perfectpixel-review'] = '{{download_review_column}}';
	}
	return $columns;
}

function perfectpixel_customer_reviewed( $product_id ) {
	return (bool) get_comments(
		array(
			'post_id' => $product_id,
			'user_id' => get_current_user_id(),
			'type'    => 'review',
			'count'   => true,
			'status'  => 'all',
		)
	);
}

function perfectpixel_review_column_value( $download ) {
	$product_id = (int) $download['product_id'];
	$product    = wc_get_product( $product_id );
	if ( $product && $product->get_parent_id() ) {
		$product_id = $product->get_parent_id();
	}
	if ( $product_id && comments_open( $product_id ) && ! perfectpixel_customer_reviewed( $product_id ) ) {
		echo '<a class="button" href="' . esc_url( get_permalink( $product_id ) . '#reviews' ) . '">' . esc_html( '{{download_review_button}}' ) . '</a>';
	}
}
